// Composition root (foundation-owned). The only file that imports every module's
// factory. Feature agents implement their factories in their own directories; they
// do not edit this file.
import { createAlertService } from "./alerts";
import { createRecordingStorage } from "./audio";
import { createContactsService } from "./contacts";
import { createContextService } from "./context";
import { createEventLog, type Db, type EventLog } from "./db";
import {
  createAuthGuard,
  createSessionService,
  type AuthGuard,
  type SessionService,
} from "./lib/auth";
import { systemClock, type Clock } from "./lib/clock";
import type { HavenConfig } from "./lib/config";
import type {
  AlertService,
  ContactsService,
  HavenContextService,
  HavenNotificationService,
  HavenRecordingStorage,
  PhotonWebhookHandler,
  ServiceContext,
} from "./lib/interfaces";
import { createLogger, type Logger } from "./lib/logger";
import { createNotificationService, createPhotonWebhookHandler } from "./photon";

export interface ServiceContainer {
  config: HavenConfig;
  db: Db;
  clock: Clock;
  logger: Logger;
  events: EventLog;
  sessions: SessionService;
  auth: AuthGuard;
  contacts: ContactsService;
  notifications: HavenNotificationService;
  context: HavenContextService;
  alerts: AlertService;
  recordings: HavenRecordingStorage;
  photonWebhooks: PhotonWebhookHandler;
}

/** Replace any module, e.g. with fakes from src/testing in tests. */
export type ServiceOverrides = Partial<
  Pick<
    ServiceContainer,
    "contacts" | "notifications" | "context" | "alerts" | "recordings" | "photonWebhooks"
  >
>;

export function createContainer(
  config: HavenConfig,
  options: { db: Db; clock?: Clock; logger?: Logger; overrides?: ServiceOverrides },
): ServiceContainer {
  const clock = options.clock ?? systemClock;
  const logger = options.logger ?? createLogger();
  const events = createEventLog(options.db, clock);
  const ctx: ServiceContext = { config, db: options.db, clock, logger, events };
  const o = options.overrides ?? {};

  const sessions = createSessionService({ db: options.db, clock, pairingCode: config.pairingCode });
  const contacts = o.contacts ?? createContactsService(ctx);
  const notifications = o.notifications ?? createNotificationService(ctx);
  const context = o.context ?? createContextService(ctx);
  const alerts = o.alerts ?? createAlertService(ctx, { contacts, notifications, context });
  const recordings = o.recordings ?? createRecordingStorage(ctx);
  const photonWebhooks = o.photonWebhooks ?? createPhotonWebhookHandler(ctx);

  return {
    config,
    db: options.db,
    clock,
    logger,
    events,
    sessions,
    auth: createAuthGuard(sessions),
    contacts,
    notifications,
    context,
    alerts,
    recordings,
    photonWebhooks,
  };
}
